<?php require_once __DIR__.'/../includes/bootstrap.php'; require_login(); $uid=(int)$_SESSION['user']['id'];$q=$pdo->prepare('SELECT COUNT(*) FROM applications WHERE user_id=?');$q->execute([$uid]);$total=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM applications WHERE user_id=? AND status IN ('Shortlisted','Interview','Offer')');$q->execute([$uid]);$progress=(int)$q->fetchColumn();$jobs=$pdo->query('SELECT * FROM opportunities WHERE is_active=1 ORDER BY created_at DESC')->fetchAll();$q=$pdo->prepare('SELECT a.id,a.status,a.applied_at,o.title,o.company FROM applications a JOIN opportunities o ON o.id=a.opportunity_id WHERE a.user_id=? ORDER BY a.applied_at DESC LIMIT 5');$q->execute([$uid]);$apps=$q->fetchAll();header_html('Student Dashboard'); ?>
<div class="row"><div><h1>Student dashboard</h1><p class="muted">Find opportunities and manage your applications.</p></div><a class="btn" href="#opportunities">Explore roles</a></div><div class="stats"><div class="stat"><span class="muted">Applications</span><strong><?=$total?></strong></div><div class="stat"><span class="muted">In progress / selected</span><strong><?=$progress?></strong></div><div class="stat"><span class="muted">Open opportunities</span><strong><?=count($jobs)?></strong></div></div>
<section class="panel"><h2>My recent applications</h2><?php if(!$apps):?><p class="empty">No applications yet. Explore opportunities below.</p><?php else:?><div class="table-wrap"><table><tr><th>Company / Role</th><th>Applied</th><th>Status</th></tr><?php foreach($apps as $a):?><tr><td><strong><?=e($a['company'])?></strong><br><?=e($a['title'])?></td><td><?=e(date('d M Y',strtotime($a['applied_at'])))?></td><td><span class="status <?=e($a['status'])?>"><?=e($a['status'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?></section>
<h2 id="opportunities">Open opportunities</h2><div class="grid"><?php foreach($jobs as $job):?><article class="card"><span class="tag"><?=e($job['type'])?></span><h3><?=e($job['title'])?></h3><strong><?=e($job['company'])?></strong><p class="muted"><?=e($job['location'])?> · <?=e($job['work_mode'])?></p><p><?=e($job['description'])?></p><p><strong>Stipend / Salary:</strong> <?=e($job['compensation']?:'Not specified')?></p><p class="small muted">Skills: <?=e($job['skills']?:'Not specified')?></p><?php $q=$pdo->prepare('SELECT id FROM applications WHERE user_id=? AND opportunity_id=?');$q->execute([$uid,$job['id']]);$already=(bool)$q->fetchColumn();if($already):?><span class="tag">Applied</span><?php else:?><form method="post" action="apply.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="opportunity_id" value="<?=$job['id']?>"><div class="field"><label>Why are you a good fit? (20–500 characters)</label><textarea name="cover_letter" required minlength="20" maxlength="500" placeholder="Describe your relevant skills..."></textarea></div><button type="submit">Apply now</button></form><?php endif;?></article><?php endforeach;?></div><?php footer_html(); ?>
